//
// E2E 01 · E2E 02 · E2E 03 (P0) — Plano_de_Testes_QA_MatchWallet.md §14 (docs-test/areas/e2e.md).
// Jornadas completas contra backend + banco de teste reais, preparadas pela API (não há UI para
// cadastrar cliente, criar/publicar versão nem vincular carteira) e conferidas também na UI do
// cliente. Cada jornada usa clientes DESCARTÁVEIS; o admin real só executa as ações de equipe.
//
// Desvios do roteiro do plano, porque o sistema não oferece o passo:
//  - "Administrador cadastra cliente" → auto-cadastro (`POST /auth/register`); não há cadastro
//    pelo admin (ver `FormularioUsuario.vue` órfão).
//  - "Primeiro acesso e aceite" → não existe consentimento (CON 03).
//  - "Equipe realiza vínculo" → o vínculo nasce da própria avaliação (`POST /suitability/avaliar`
//    grava `usuario_carteira_historico`); não existe endpoint de vínculo manual.
//  - "Cliente com relatório em M-1" → o vínculo começa "agora", então não dá para fabricar um
//    cliente elegível a M-1; o E2E 03 prova a preservação com o relatório de M e a inelegibilidade
//    de M-1.
//
// Efeitos colaterais no banco de teste (por design, as jornadas são re-executáveis): publica a
// versão do mês corrente (e do anterior) nas carteiras envolvidas, lança rentabilidade e gera
// relatórios com `forcar: true`. E2E 03 cria uma versão de configuração de suitability e restaura
// as faixas originais no `after`.
//
// Casos que EXPÕEM defeito conhecido (devem falhar até a correção):
//  - E2E 03 · "avaliação usa parâmetros novos": `SuitabilityService.calcularPerfil` usa faixas
//    hardcoded e não lê `configuracao_suitability` (comentário em configuracoes-suitability.service.ts).

interface Pergunta {
  id: string
  opcoes: Array<{ id: string; peso: number }>
}

interface Faixa {
  perfil: string
  min: number
  max: number
}

interface Configuracao {
  escalaMaxima: number
  faixas: Faixa[]
}

interface CarteiraResumo {
  id: string
  nome: string
  perfilAlvo: string
}

interface Resultado {
  id: string
  usuarioId: string
  pontuacaoTotal: number
  perfilResultante: string
  carteiraRecomendada: CarteiraResumo | null
  /** Soma dos pesos calculada aqui, independente do servidor. */
  somaEsperada: number
}

interface Me {
  id: string
  nome: string
  email: string
  perfil: string
  perfilInvestidor: string | null
  carteiraVinculada: CarteiraResumo | null
}

interface VersaoResumo {
  id: string
  mesReferencia: string
  publicada: boolean
}

interface RelatorioGerado {
  id: string
  carteiraId: string
  mesReferencia: string
  nomeArquivo: string
}

interface RelatorioDoCliente {
  id: string
  carteiraId?: string
  mesReferencia: string
  nomeArquivo?: string
}

interface Conta {
  id: string
  email: string
  senha: string
}

type Escolha = 'maior' | 'menor'

const NEGADO = [401, 403]

/** Competência `AAAA-MM` (UTC) deslocada `meses` do mês corrente. */
function competencia(meses = 0): string {
  const agora = new Date()
  const data = new Date(Date.UTC(agora.getUTCFullYear(), agora.getUTCMonth() + meses, 1))
  return data.toISOString().slice(0, 7)
}

function comoAdmin() {
  cy.clearCookies()
  cy.loginReal('admin')
}

function comoCliente(conta: Conta) {
  cy.clearCookies()
  cy.loginComo(conta)
}

function me() {
  return cy.apiRequest<Me>({ method: 'GET', url: '/auth/me' }).its('body')
}

/** Responde todas as perguntas escolhendo sempre a opção de maior (ou menor) peso. */
function avaliar(conta: Conta, escolha: Escolha): Cypress.Chainable<Resultado> {
  return cy
    .apiRequest<Pergunta[]>({ method: 'GET', url: '/suitability/perguntas' })
    .then(({ body: perguntas }) => {
      const escolhidas = perguntas.map((pergunta) => {
        const ordenadas = [...pergunta.opcoes].sort((a, b) => a.peso - b.peso)
        return {
          perguntaId: pergunta.id,
          opcao: escolha === 'maior' ? ordenadas.at(-1) : ordenadas[0],
        }
      })
      const somaEsperada = escolhidas.reduce((total, e) => total + (e.opcao?.peso ?? 0), 0)

      return cy
        .apiRequest<Omit<Resultado, 'somaEsperada'>>({
          method: 'POST',
          url: '/suitability/avaliar',
          body: {
            usuarioId: conta.id,
            respostas: escolhidas.map((e) => ({ perguntaId: e.perguntaId, opcaoId: e.opcao?.id })),
          },
        })
        .then(({ body }) => ({ ...body, somaEsperada }))
    })
}

/** Até 4 ativos de referência, tirados da primeira carteira que já tem versão vigente. */
function ativosDeReferencia(): Cypress.Chainable<string[]> {
  const ativoIds: string[] = []

  return cy
    .apiRequest<{ items: Array<{ id: string }> }>({ method: 'GET', url: '/carteiras?pageSize=100' })
    .then(({ body }) => {
      for (const { id } of body.items) {
        cy.apiRequest<{ versaoAtual: { itens: Array<{ ativoId: string }> } | null }>({
          method: 'GET',
          url: `/carteiras/${id}`,
        }).then(({ body: detalhe }) => {
          if (ativoIds.length === 0 && detalhe.versaoAtual) {
            for (const { ativoId } of detalhe.versaoAtual.itens.slice(0, 4)) ativoIds.push(ativoId)
          }
        })
      }
      return cy.then(() => ativoIds)
    })
}

/** Divide 100% entre `n` ativos em 2 casas, com o resto no primeiro (soma exata de 100). */
function pesosIguais(n: number): number[] {
  const base = Math.floor(10000 / n) / 100
  const resto = Math.round((100 - base * n) * 100) / 100
  return Array.from({ length: n }, (_, i) =>
    i === 0 ? Math.round((base + resto) * 100) / 100 : base,
  )
}

/** Garante versão PUBLICADA da carteira na competência (cria se faltar; tolera re-execução). Exige admin. */
function garantirVersaoPublicada(carteiraId: string, mesReferencia: string) {
  const listarVersoes = () =>
    cy
      .apiRequest<{ items: VersaoResumo[] }>({
        method: 'GET',
        url: `/carteiras/${carteiraId}/versoes?pageSize=100`,
      })
      .its('body.items')

  listarVersoes().then((versoes) => {
    if (versoes.some((v: VersaoResumo) => v.mesReferencia === mesReferencia)) return

    ativosDeReferencia().then((ativoIds) => {
      expect(
        ativoIds,
        'ativos de referência (alguma carteira precisa ter versão vigente)',
      ).to.have.length.greaterThan(0)
      const pesos = pesosIguais(ativoIds.length)
      cy.apiRequest({
        method: 'POST',
        url: `/carteiras/${carteiraId}/versoes`,
        body: {
          mesReferencia,
          itens: ativoIds.map((ativoId, i) => ({ ativoId, pesoPercentual: pesos[i] })),
        },
      })
        .its('status')
        .should('eq', 201)
    })
  })

  listarVersoes().then((versoes) => {
    const versao = versoes.find((v: VersaoResumo) => v.mesReferencia === mesReferencia)
    expect(versao, `versão de ${mesReferencia}`).to.exist
    if (versao?.publicada) return

    cy.apiRequest({
      method: 'POST',
      url: `/carteiras/${carteiraId}/versoes/${versao?.id}/publicar`,
    })
      .its('status')
      .should('be.within', 200, 201)
  })
}

/** Publica a versão (se preciso) e gera o relatório da competência, substituindo um anterior. Exige admin. */
function garantirRelatorio(carteiraId: string, mesReferencia: string) {
  garantirVersaoPublicada(carteiraId, mesReferencia)

  return cy
    .apiRequest<RelatorioGerado>({
      method: 'POST',
      url: '/relatorios/gerar',
      body: {
        carteiraId,
        mesReferencia,
        comentarioMercado: 'Relatório gerado pelo E2E.',
        forcar: true,
      },
    })
    .then(({ status, body }) => {
      expect(status).to.eq(201)
      expect(body.carteiraId).to.eq(carteiraId)
      expect(body.mesReferencia).to.eq(mesReferencia)
      return body
    })
}

function meusRelatorios(): Cypress.Chainable<RelatorioDoCliente[]> {
  return cy
    .apiRequest<{ items: RelatorioDoCliente[] }>({
      method: 'GET',
      url: '/relatorios/meus-relatorios?pageSize=100',
    })
    .its('body.items')
}

describe('Plano QA · Jornadas completas de aceitação', () => {
  it('E2E 01 · cliente do cadastro à recomendação → mesma identidade, perfil e vínculo em toda a jornada e nenhuma ação administrativa', () => {
    // 1–2. Cadastro (auto-cadastro; ver "Desvios" no topo) e primeiro acesso.
    cy.criarUsuarioDescartavel().then((conta) => {
      comoCliente(conta)
      me().then((inicial) => {
        expect(inicial.id).to.eq(conta.id)
        expect(inicial.email).to.eq(conta.email)
        expect(inicial.perfil).to.eq('cliente')
        expect(inicial.perfilInvestidor, 'antes da avaliação').to.eq(null)
        expect(inicial.carteiraVinculada, 'antes da avaliação').to.eq(null)
      })

      // 3–4. Avaliação com resultado conhecido; o vínculo nasce junto com ela.
      avaliar(conta, 'maior').then((resultado) => {
        expect(resultado.usuarioId).to.eq(conta.id)
        expect(resultado.pontuacaoTotal, 'pontuação = soma dos pesos').to.eq(resultado.somaEsperada)
        expect(resultado.carteiraRecomendada, 'carteira elegível para o perfil').not.to.eq(null)
        const carteira = resultado.carteiraRecomendada as CarteiraResumo
        expect(carteira.perfilAlvo).to.eq(resultado.perfilResultante)

        // 5a. API: a identidade e o vínculo batem em todas as leituras do cliente.
        me().then((depois) => {
          expect(depois.id).to.eq(conta.id)
          expect(depois.email).to.eq(conta.email)
          expect(depois.perfilInvestidor).to.eq(resultado.perfilResultante)
          expect(depois.carteiraVinculada?.id).to.eq(carteira.id)
        })
        cy.apiRequest({ method: 'GET', url: '/dashboard/investidor' })
          .its('status')
          .should('eq', 200)
        cy.apiRequest({ method: 'GET', url: '/relatorios/meus-relatorios' })
          .its('status')
          .should('eq', 200)
        cy.apiRequest<{ items: CarteiraResumo[] }>({
          method: 'GET',
          url: '/carteiras?pageSize=100',
        })
          .its('body.items')
          .should((itens) => {
            expect(itens.map((c: CarteiraResumo) => c.id)).to.include(carteira.id)
          })

        // 5b. UI do cliente: painel, minha carteira, catálogo e conta sem redirecionar.
        cy.visit('/')
        cy.location('pathname').should('eq', '/')
        cy.visit('/carteira')
        cy.location('pathname').should('eq', '/carteira')
        cy.visit('/carteiras')
        cy.contains('[data-slot="wallet-card"]', carteira.nome)
          .should('contain.text', 'sua carteira')
          .and('contain.text', carteira.perfilAlvo)
        cy.visit('/conta')
        cy.contains('dd', conta.email).should('be.visible')
        cy.contains('dd', carteira.nome).should('be.visible')
        cy.contains(resultado.perfilResultante).should('be.visible')
      })

      // Nenhum passo administrativo é permitido ao cliente: API e rotas.
      for (const url of ['/usuarios', '/dashboard/admin']) {
        cy.apiRequest({ method: 'GET', url, failOnStatusCode: false })
          .its('status', { log: false })
          .should('be.oneOf', NEGADO)
      }
      cy.apiRequest({
        method: 'POST',
        url: '/carteiras',
        body: { nome: 'Invasora E2E', perfilAlvo: 'MODERADO' },
        failOnStatusCode: false,
      })
        .its('status')
        .should('be.oneOf', NEGADO)
      cy.visit('/admin')
      cy.location('pathname').should('eq', '/403')
    })
  })

  it('E2E 02 · publicação, rentabilidade e relatório até o cliente → dados reconciliados e PDF da competência e da carteira certas', () => {
    const mes = competencia()
    const valores = {
      rentabilidadeMes: 1.5,
      rentabilidadeAcumuladaAno: 1.5,
      cdiMes: 1,
      ibovMes: 0.5,
    }

    cy.criarUsuarioDescartavel().then((conta) => {
      // Cliente vinculado à carteira do seu perfil, a partir de agora (cobre o mês corrente).
      comoCliente(conta)
      avaliar(conta, 'maior').then((resultado) => {
        const carteiraId = resultado.carteiraRecomendada?.id as string
        expect(carteiraId, 'carteira vinculada').to.be.a('string')

        // 1–3. Equipe: versão publicada, rentabilidade lançada e relatório gerado.
        comoAdmin()
        garantirVersaoPublicada(carteiraId, mes)

        cy.apiRequest<{ avisos?: string[]; acumuladoCalculado?: number }>({
          method: 'POST',
          url: `/carteiras/${carteiraId}/rentabilidade`,
          body: { mesReferencia: mes, ...valores },
          failOnStatusCode: false,
        }).then(({ status }) => {
          // 409 = já lançada em execução anterior; o PUT abaixo corrige para os valores deste teste.
          expect(status).to.be.oneOf([201, 409])
        })
        // Reconcilia o acumulado do ano com o que o servidor compõe dos lançamentos do ano.
        cy.apiRequest<{ avisos?: string[]; acumuladoCalculado?: number }>({
          method: 'PUT',
          url: `/carteiras/${carteiraId}/rentabilidade/${mes}`,
          body: valores,
        }).then(({ body }) => {
          if (body.avisos?.includes('ACUMULADO_DIVERGENTE')) {
            cy.apiRequest<{ avisos?: string[] }>({
              method: 'PUT',
              url: `/carteiras/${carteiraId}/rentabilidade/${mes}`,
              body: { ...valores, rentabilidadeAcumuladaAno: body.acumuladoCalculado },
            })
              .its('body.avisos')
              .should('not.exist')
          }
        })

        garantirRelatorio(carteiraId, mes).then((gerado) => {
          // 4. Fechamento administrativo: a série da carteira traz o mês lançado com os números certos.
          cy.apiRequest<{
            serie: Array<{
              mesReferencia: string
              rentabilidade: number
              cdi: number
              ibov: number
              percentualCdi: number | null
            }>
          }>({
            method: 'GET',
            url: `/carteiras/${carteiraId}/historico-performance?periodoMeses=12`,
          })
            .its('body.serie')
            .should((serie) => {
              const linha = serie.find((l: { mesReferencia: string }) => l.mesReferencia === mes)
              expect(linha, `linha de ${mes} na série`).to.exist
              expect(linha?.rentabilidade).to.eq(valores.rentabilidadeMes)
              expect(linha?.cdi).to.eq(valores.cdiMes)
              expect(linha?.ibov).to.eq(valores.ibovMes)
              expect(linha?.percentualCdi).to.be.closeTo(150, 0.01)
            })

          // 5. Cliente consulta e baixa o relatório.
          comoCliente(conta)
          meusRelatorios().should((itens) => {
            const meu = itens.find((r) => r.id === gerado.id)
            expect(meu, 'relatório gerado aparece no acervo do cliente').to.exist
            expect(meu?.mesReferencia).to.eq(mes)
          })

          cy.apiRequest<string>({
            method: 'GET',
            url: `/relatorios/${gerado.id}/download`,
            encoding: 'binary',
          }).then(({ status, headers, body }) => {
            expect(status).to.eq(200)
            expect(String(headers['content-type'])).to.contain('application/pdf')
            // Nome do arquivo identifica carteira e competência.
            expect(String(headers['content-disposition'])).to.contain(gerado.nomeArquivo)
            expect(gerado.nomeArquivo).to.contain(mes)
            expect(body.slice(0, 4), 'assinatura do PDF').to.eq('%PDF')
          })

          cy.visit('/relatorios')
          cy.location('pathname').should('eq', '/relatorios')
        })
      })
    })
  })

  describe('E2E 03 · reavaliação e preservação histórica', () => {
    let configuracaoOriginal: Configuracao | undefined

    // Reset antes dos testes: guarda a configuração para restaurá-la no `after`.
    before(() => {
      comoAdmin()
      cy.apiRequest<Configuracao>({ method: 'GET', url: '/configuracoes/suitability' })
        .its('body')
        .then((configuracao) => {
          configuracaoOriginal = configuracao
        })
    })

    after(() => {
      if (!configuracaoOriginal) return
      comoAdmin()
      cy.apiRequest({
        method: 'PUT',
        url: '/configuracoes/suitability',
        body: configuracaoOriginal,
      })
        .its('status')
        .should('be.within', 200, 201)
    })

    it('E2E 03 · cliente reavalia com mudança de perfil → vínculo novo, histórico e relatório antigo preservados, M-1 inelegível', () => {
      const mes = competencia()
      const mesAnterior = competencia(-1)

      cy.criarUsuarioDescartavel().then((conta) => {
        comoCliente(conta)

        // Avaliação 1 (perfil alto) → carteira 1.
        avaliar(conta, 'maior').then((primeira) => {
          const carteira1 = primeira.carteiraRecomendada as CarteiraResumo
          expect(carteira1, 'carteira da primeira avaliação').not.to.eq(null)

          // Equipe fecha o mês da carteira 1; o cliente (vinculado) enxerga o relatório.
          comoAdmin()
          garantirRelatorio(carteira1.id, mes).then((relatorio1) => {
            comoCliente(conta)
            meusRelatorios().should((itens) => {
              expect(itens.map((r) => r.id)).to.include(relatorio1.id)
            })

            // Avaliação 2 (perfil baixo) → muda de perfil e de carteira.
            avaliar(conta, 'menor').then((segunda) => {
              const carteira2 = segunda.carteiraRecomendada as CarteiraResumo
              expect(carteira2, 'carteira da segunda avaliação').not.to.eq(null)
              expect(
                segunda.perfilResultante,
                'o perfil precisa mudar para o caso valer',
              ).not.to.eq(primeira.perfilResultante)
              expect(carteira2.id).not.to.eq(carteira1.id)

              me().then((depois) => {
                expect(depois.id).to.eq(conta.id)
                expect(depois.perfilInvestidor).to.eq(segunda.perfilResultante)
                expect(depois.carteiraVinculada?.id).to.eq(carteira2.id)
              })

              // Equipe fecha o mês da nova carteira e prepara M-1 da antiga (período em que o
              // cliente nunca esteve vinculado).
              comoAdmin()
              garantirRelatorio(carteira2.id, mes)
              garantirRelatorio(carteira1.id, mesAnterior).then((relatorioAnterior) => {
                // Histórico de avaliações preservado e na ordem certa (visão admin).
                cy.apiRequest<Array<{ pontuacaoTotal: number; perfilResultante: string }>>({
                  method: 'GET',
                  url: `/usuarios/${conta.id}/historico-suitability`,
                })
                  .its('body')
                  .should((historico) => {
                    expect(historico).to.have.length(2)
                    const pontuacoes = historico.map((h) => h.pontuacaoTotal).sort((a, b) => a - b)
                    expect(pontuacoes).to.deep.eq(
                      [primeira.pontuacaoTotal, segunda.pontuacaoTotal].sort((a, b) => a - b),
                    )
                  })

                comoCliente(conta)
                meusRelatorios().should((itens) => {
                  const ids = itens.map((r) => r.id)
                  // Documento histórico da carteira antiga em M continua acessível...
                  expect(ids, 'relatório de M da carteira anterior').to.include(relatorio1.id)
                  // ...e M-1 da carteira antiga nunca foi elegível.
                  expect(ids, 'relatório de M-1 (inelegível)').not.to.include(relatorioAnterior.id)
                })

                cy.apiRequest({ method: 'GET', url: `/relatorios/${relatorio1.id}/download` })
                  .its('status')
                  .should('eq', 200)
                cy.apiRequest({
                  method: 'GET',
                  url: `/relatorios/${relatorioAnterior.id}/download`,
                  failOnStatusCode: false,
                })
                  .its('status')
                  .should('be.oneOf', [403, 404])
              })
            })
          })
        })
      })
    })

    it('E2E 03 · nova versão de parâmetros e reavaliação → a classificação usa as faixas novas (falha até o servidor ler a configuração)', () => {
      comoAdmin()
      cy.apiRequest<Configuracao>({ method: 'GET', url: '/configuracoes/suitability' })
        .its('body')
        .then((atual) => {
          // Faixas novas e contíguas: quase todo mundo vira SOFISTICADO. Diferem das faixas fixas
          // do servidor (0–14 / 15–29 / 30–44 / 45+) para qualquer pontuação entre 3 e 44.
          const novas: Faixa[] = [
            { perfil: 'CONSERVADOR', min: 0, max: 0 },
            { perfil: 'MODERADO', min: 1, max: 1 },
            { perfil: 'ARROJADO', min: 2, max: 2 },
            { perfil: 'SOFISTICADO', min: 3, max: atual.escalaMaxima },
          ]
          cy.apiRequest({
            method: 'PUT',
            url: '/configuracoes/suitability',
            body: { escalaMaxima: atual.escalaMaxima, faixas: novas },
          })
            .its('status')
            .should('be.within', 200, 201)

          cy.criarUsuarioDescartavel().then((conta) => {
            comoCliente(conta)
            avaliar(conta, 'menor').then((resultado) => {
              const esperado = novas.find(
                (f) => resultado.somaEsperada >= f.min && resultado.somaEsperada <= f.max,
              )
              expect(esperado, `faixa nova para ${resultado.somaEsperada} pontos`).to.exist
              expect(
                resultado.somaEsperada,
                'caso só vale se as faixas novas mudam o resultado',
              ).to.be.within(3, 44)
              expect(resultado.perfilResultante).to.eq(esperado?.perfil)
            })
          })
        })
    })
  })
})

export {}
